class Solution:
    def maxArea(self, mat):
        m, n = len(mat), len(mat[0])
        P = [[0] * (n + 1) for _ in range(m + 1)]
        for i in range(m):
            for j in range(n):
                P[i+1][j+1] = P[i][j+1] + P[i+1][j] - P[i][j] + mat[i][j]
        def ok(r, c, k):
            return P[r+k][c+k] - P[r][c+k] - P[r+k][c] + P[r][c] == k * k
        def feas(k):
            rh = [False] * m
            ch = [False] * n
            for r in range(m - k + 1):
                for c in range(n - k + 1):
                    if ok(r, c, k):
                        rh[r] = ch[c] = True
            return any(rh[r] and rh[r+k] for r in range(m - 2*k + 1)) or \
                   any(ch[c] and ch[c+k] for c in range(n - 2*k + 1))
        lo, hi, ans = 1, min(m, n), 0
        while lo <= hi:
            mid = (lo + hi) // 2
            if feas(mid):
                ans = mid * mid
                lo = mid + 1
            else:
                hi = mid - 1
        return ans

