class Solution {
public:
    int maxArea(vector<vector<int>>& mat) {
        int m = mat.size(), n = mat[0].size();
        vector<vector<int>> P(m + 1, vector<int>(n + 1, 0));
        for (int i = 0; i < m; i++)
            for (int j = 0; j < n; j++)
                P[i+1][j+1] = P[i][j+1] + P[i+1][j] - P[i][j] + mat[i][j];
        auto ok = [&](int r, int c, int k) {
            return P[r+k][c+k] - P[r][c+k] - P[r+k][c] + P[r][c] == k * k;
        };
        auto feas = [&](int k) {
            vector<char> rh(m, 0), ch(n, 0);
            for (int r = 0; r + k <= m; r++)
                for (int c = 0; c + k <= n; c++)
                    if (ok(r, c, k)) { rh[r] = ch[c] = 1; }
            for (int r = 0; r + 2*k <= m; r++) if (rh[r] && rh[r+k]) return true;
            for (int c = 0; c + 2*k <= n; c++) if (ch[c] && ch[c+k]) return true;
            return false;
        };
        int lo = 1, hi = min(m, n), ans = 0;
        while (lo <= hi) {
            int mid = (lo + hi) / 2;
            if (feas(mid)) { ans = mid * mid; lo = mid + 1; }
            else hi = mid - 1;
        }
        return ans;
    }
};

