class Solution {
    public int maxArea(int[][] mat) {
        int m = mat.length, n = mat[0].length;
        int[][] P = new int[m + 1][n + 1];
        for (int i = 0; i < m; i++)
            for (int j = 0; j < n; j++)
                P[i+1][j+1] = P[i][j+1] + P[i+1][j] - P[i][j] + mat[i][j];
        for (int k = Math.min(m, n); k >= 1; k--) {
            if (feas(P, m, n, k)) return k * k;
        }
        return 0;
    }
    private boolean feas(int[][] P, int m, int n, int k) {
        boolean[] rh = new boolean[m], ch = new boolean[n];
        for (int r = 0; r + k <= m; r++)
            for (int c = 0; c + k <= n; c++)
                if (P[r+k][c+k] - P[r][c+k] - P[r+k][c] + P[r][c] == k * k) {
                    rh[r] = true; ch[c] = true;
                }
        for (int r = 0; r + 2*k <= m; r++) if (rh[r] && rh[r+k]) return true;
        for (int c = 0; c + 2*k <= n; c++) if (ch[c] && ch[c+k]) return true;
        return false;
    }
}

