class Solution:
    def maxArea(self, mat):
        m, n = len(mat), len(mat[0])
        br = [[0] * n for _ in range(m)]
        tl = [[0] * n for _ in range(m)]
        for r in range(m):
            for c in range(n):
                if mat[r][c]:
                    br[r][c] = 1 + min(br[r-1][c] if r else 0,
                                       br[r][c-1] if c else 0,
                                       br[r-1][c-1] if r and c else 0)
        for r in range(m - 1, -1, -1):
            for c in range(n - 1, -1, -1):
                if mat[r][c]:
                    tl[r][c] = 1 + min(tl[r+1][c] if r < m-1 else 0,
                                       tl[r][c+1] if c < n-1 else 0,
                                       tl[r+1][c+1] if r < m-1 and c < n-1 else 0)
        g = [[0] * n for _ in range(m)]
        h = [[0] * n for _ in range(m)]
        for r in range(m):
            for c in range(n):
                g[r][c] = max(br[r][c], g[r-1][c] if r else 0, g[r][c-1] if c else 0)
        for r in range(m - 1, -1, -1):
            for c in range(n - 1, -1, -1):
                h[r][c] = max(tl[r][c], h[r+1][c] if r < m-1 else 0, h[r][c+1] if c < n-1 else 0)
        ans = 0
        for r in range(m - 1):
            ans = max(ans, min(g[r][n-1], h[r+1][0]))
        for c in range(n - 1):
            ans = max(ans, min(g[m-1][c], h[0][c+1]))
        return ans * ans

