        int[][] br = new int[m][n], tl = new int[m][n];
        for (int r = 0; r < m; r++)
            for (int c = 0; c < n; c++)
                if (mat[r][c] == 1)
                    br[r][c] = 1 + Math.min(Math.min(r > 0 ? br[r-1][c] : 0,
                                                     c > 0 ? br[r][c-1] : 0),
                                            (r > 0 && c > 0) ? br[r-1][c-1] : 0);
        for (int r = m - 1; r >= 0; r--)
            for (int c = n - 1; c >= 0; c--)
                if (mat[r][c] == 1)
                    tl[r][c] = 1 + Math.min(Math.min(r < m-1 ? tl[r+1][c] : 0,
                                                     c < n-1 ? tl[r][c+1] : 0),
                                            (r < m-1 && c < n-1) ? tl[r+1][c+1] : 0);
        int[][] g = new int[m][n], h = new int[m][n];
        for (int r = 0; r < m; r++)
            for (int c = 0; c < n; c++)
                g[r][c] = Math.max(br[r][c], Math.max(r > 0 ? g[r-1][c] : 0,
                                                      c > 0 ? g[r][c-1] : 0));
        for (int r = m - 1; r >= 0; r--)
            for (int c = n - 1; c >= 0; c--)
                h[r][c] = Math.max(tl[r][c], Math.max(r < m-1 ? h[r+1][c] : 0,
                                                      c < n-1 ? h[r][c+1] : 0));
