        for (int r = 0; r + 1 < m; r++) ans = Math.max(ans, Math.min(g[r][n-1], h[r+1][0]));
        for (int c = 0; c + 1 < n; c++) ans = Math.max(ans, Math.min(g[m-1][c], h[0][c+1]));
